static PyObject *
Opcode_new(PyTypeObject *type, PyObject *args, PyObject *kwds)
{
    if (type != CPyType_Opcode) {
        PyErr_SetString(PyExc_TypeError, "interpreted classes cannot inherit from compiled");
        return NULL;
    }
    PyObject *self = Opcode_setup(type);
    if (self == NULL)
        return NULL;
    PyObject *ret = CPyPy_Opcode_____init__(self, args, kwds);
    if (ret == NULL)
        return NULL;
    return self;
}

